                envGroupStorage: 'Speicher: Kontingente & Schlüssel (Backend)',
                envGroupStorageNote: 'Standard-Kontingente und Größenlimits für hochgeladene Dateien. STORAGE_CREDENTIALENCRYPTIONKEY ist zwingend zu setzen, sobald eine Wache S3/SMB/SFTP über die Admin-Oberfläche konfigurieren soll.',
